.profile-card {
  display: flex;
  gap: 1rem;
  align-items: flex-start;
  max-width: 32rem;
  padding: 1.25rem;
  border: 1px solid #cbd5e1;
  border-radius: 1rem;
  background: #ffffff;
}

.profile-card__link { color: #0f766e; font-weight: 700; }
.profile-card__link:hover { color: #115e59; }

@media (max-width:  thirtyrem) {
  .profile-card { flex-direction: column; }
}
